"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["72136"],{72386(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.retificacao.ciclo_novo_nao_declarado","status":422,"titulo":"A retifica\xe7\xe3o exige declarar o novo ciclo do resultado preliminar j\xe1 publicado"},"descricao":{"codigo":"uniplus.selecao.retificacao.ciclo_novo_nao_declarado","requisitos":["UNI-REQ-0157","UNI-REQ-0282"],"oQueAconteceu":["A retifica\xe7\xe3o muda a regra ou os dados de entrada de um resultado preliminar que j\xe1 foi publicado, e o pedido n\xe3o declara o novo ciclo desse resultado. O novo resultado preliminar precisa ser publicado antes do definitivo, e por isso o pedido declara o novo ciclo de cada resultado nessa condi\xe7\xe3o.","A recusa \xe9 **422** e n\xe3o aponta campo: a mensagem cita o c\xf3digo do ato do resultado preliminar que ficou sem declara\xe7\xe3o. Uma recusa \xe9 devolvida para cada resultado nessa condi\xe7\xe3o, em ordem do identificador do item, e as recusas de ciclo declarado sem preliminar aberto v\xeam depois."],"comoResolver":["Declare, no pedido de retifica\xe7\xe3o, o novo ciclo de cada resultado preliminar citado na mensagem. Se a mudan\xe7a n\xe3o deveria alterar o resultado j\xe1 publicado, ajuste a retifica\xe7\xe3o para n\xe3o mexer na regra nem nos dados de entrada daquele resultado."]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Retificacao"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"e5dad467d85ce0f062b88f68241ad834bc540cf0"}}')}}]);